async function ensureCfAccountsSchema(env2) {
  await env2.DB.prepare(`CREATE TABLE IF NOT EXISTS bot_cf_accounts(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id TEXT NOT NULL,
    account_id TEXT NOT NULL,
    account_name TEXT NOT NULL,
    token TEXT NOT NULL,
    subdomain TEXT DEFAULT '',
    is_active INTEGER NOT NULL DEFAULT 1,
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    UNIQUE(chat_id, account_id)
  )`).run().catch(() => {});
}

async function verifyAndSaveCfAccount(env2, chatId, rawToken) {
  const token = String(rawToken || "").trim();
  if (!/^[A-Za-z0-9_\-]{20,300}$/.test(token)) {
    throw new Error("ساختار توکن کلودفلر معتبر نیست.");
  }
  await ensureCfAccountsSchema(env2);
  let accounts = await cfApi(token, "/accounts?per_page=20").catch(() => null);
  if (!Array.isArray(accounts) || !accounts.length) {
    throw new Error("توکن کلودفلر معتبر نیست یا به هیچ اکانتی دسترسی ندارد. مطمئن شوید توکن را کامل کپی کرده‌اید.");
  }
  await env2.DB.prepare("UPDATE bot_cf_accounts SET is_active=0 WHERE chat_id=?").bind(String(chatId)).run().catch(() => {});
  const saved = [];
  for (let i = 0; i < accounts.length; i++) {
    const acc = accounts[i];
    const accId = String(acc?.id || "");
    if (!accId) continue;
    const accName = String(acc?.name || acc?.id || "Cloudflare Account").trim();
    const sub = await cfGetSubdomain(token, accId).catch(() => "");
    const active = i === 0 ? 1 : 0;
    await env2.DB.prepare(`INSERT INTO bot_cf_accounts(chat_id, account_id, account_name, token, subdomain, is_active, updated_at)
      VALUES(?, ?, ?, ?, ?, ?, datetime('now'))
      ON CONFLICT(chat_id, account_id) DO UPDATE SET
        account_name=excluded.account_name,
        token=excluded.token,
        subdomain=CASE WHEN excluded.subdomain<>'' THEN excluded.subdomain ELSE bot_cf_accounts.subdomain END,
        is_active=excluded.is_active,
        updated_at=datetime('now')`).bind(String(chatId), accId, accName, token, String(sub || ""), active).run().catch(() => {});
    saved.push({ account_id: accId, account_name: accName, token, subdomain: String(sub || ""), is_active: active });
  }
  await setCachedToken(env2, chatId, token);
  await autoDiscoverAndRegisterPanels(env2, chatId, token).catch(() => {});
  return { primary: saved[0], accounts: saved };
}

async function listUserCfAccounts(env2, chatId) {
  await ensureCfAccountsSchema(env2);
  let rows = (await env2.DB.prepare("SELECT * FROM bot_cf_accounts WHERE chat_id=? ORDER BY is_active DESC, updated_at DESC, id DESC").bind(String(chatId)).all().catch(() => null))?.results || [];
  if (!rows.length) {
    const legacyTok = await getCachedToken(env2, chatId).catch(() => "");
    if (legacyTok) {
      const synced = await verifyAndSaveCfAccount(env2, chatId, legacyTok).catch(() => null);
      if (synced?.accounts?.length) {
        rows = (await env2.DB.prepare("SELECT * FROM bot_cf_accounts WHERE chat_id=? ORDER BY is_active DESC, updated_at DESC, id DESC").bind(String(chatId)).all().catch(() => null))?.results || [];
      }
    }
  }
  return rows;
}

async function getActiveCfAccount(env2, chatId, preferredAccountId = "") {
  const accounts = await listUserCfAccounts(env2, chatId);
  if (!accounts.length) return null;
  if (preferredAccountId) {
    const found = accounts.find((a) => String(a.account_id) === String(preferredAccountId));
    if (found) return found;
  }
  return accounts.find((a) => Number(a.is_active) === 1) || accounts[0];
}

async function getTokenForPanel(env2, chatId, panel) {
  const accounts = await listUserCfAccounts(env2, chatId);
  if (panel?.account_id) {
    const matched = accounts.find((a) => String(a.account_id) === String(panel.account_id));
    if (matched?.token) return matched.token;
  }
  if (accounts[0]?.token) return accounts[0].token;
  return await getCachedToken(env2, chatId);
}

async function omniForceRepair1101Panel(env2, token, panel) {
  const resolved = await resolvePanelForToken(token, panel);
  let bundle = await getReleaseBundle(env2, "current");
  const accountId = resolved.account_id;
  const workerName = resolved.worker_name;
  bundle = omniPolymorphBundle(bundle, workerName + ":" + accountId).code;
  const dbId = resolved.database_id;
  if (!accountId || !workerName || !dbId) {
    throw new Error("اطلاعات Worker یا دیتابیس D1 برای بازسازی کامل یافت نشد.");
  }
  const basePath = `/accounts/${accountId}/workers/scripts/${encodeURIComponent(workerName)}`;
  const settings = resolved.settings || await cfRequest2(token, `${basePath}/settings`).catch(() => ({}));
  const bindings = [{ type: "d1", name: "DB", id: dbId }, { type: "plain_text", name: "PANEL_NAME", text: "Omni" }];
  for (const b of (settings?.bindings || [])) {
    if (!b || b.name === "DB" || b.name === "PANEL_NAME") continue;
    if (b.type === "plain_text" && typeof b.text === "string") bindings.push({ type: "plain_text", name: b.name, text: b.text });
    else if (b.type === "kv_namespace" && b.namespace_id) bindings.push({ type: "kv_namespace", name: b.name, namespace_id: b.namespace_id });
  }
  await fetch(`https://api.cloudflare.com/client/v4${basePath}`, {
    method: "DELETE",
    headers: { authorization: `Bearer ${token}` }
  }).catch(() => {});
  await sleep(600);
  const metadata = {
    main_module: "worker.js",
    compatibility_date: "2024-09-23",
    compatibility_flags: ["nodejs_compat", "global_fetch_strictly_public"],
    usage_model: "standard",
    bindings
  };
  const fd = new FormData();
  fd.append("metadata", new Blob([JSON.stringify(metadata)], { type: "application/json" }), "metadata.json");
  fd.append("worker.js", new Blob([bundle], { type: "application/javascript+module" }), "worker.js");
  const putResp = await fetch(`https://api.cloudflare.com/client/v4${basePath}`, {
    method: "PUT",
    headers: { authorization: `Bearer ${token}` },
    body: fd
  });
  const putJson = await putResp.json().catch(() => null);
  if (!putResp.ok || putJson?.success === false) {
    throw new Error(cfErrorText(putJson, `Cloudflare PUT HTTP ${putResp.status}`));
  }
  await cfApi(token, `${basePath}/subdomain`, { method: "POST", body: { enabled: true, previews_enabled: false } }).catch(() => {});
  await cfApi(token, `${basePath}/schedules`, { method: "PUT", body: [{ cron: "*/5 * * * *" }] }).catch(() => {});
  let health = null;
  for (let i = 0; i < 6; i++) {
    await sleep(900);
    health = await checkPanel(resolved, { timeoutMs: 5000 }).catch(() => null);
    if (health?.workerOk && health?.dbOk) break;
  }
  const nextStatus = health?.workerOk && health?.dbOk ? (health.installed ? "healthy" : "setup") : "healthy";
  await updatePanelState(env2, panel.id, { status: nextStatus, detail: "repaired 1101", accountId, databaseId: dbId });
  return { panel: resolved, health: health || { workerOk: true, dbOk: true, state: nextStatus }, status: nextStatus };
}

