    const out={domain:dom,railway:'skipped',bridge:false,job:false,cf:'skipped'};
    const railwayToken=String(b.railwayToken||'').trim()||String(job&&job.railway_token||'').trim();
    const cfToken=String(b.cfToken||'').trim()||String(job&&job.cf_token||'').trim();
