function omniRelayHumanError(raw){
  const s=String(raw||'').trim();
  if(!s)return null;
  if(/deploys? have been paused|limited access|builds? (?:are|have been) paused|deployment queue|deployments? (?:are|is) paused/i.test(s))return 'خودِ Railway الآن دیپلوی‌های جدید را موقتاً متوقف کرده (اختلال سراسری، ۲۰ و ۲۱ اکتبر ۲۰۲۶). سرویسی که از قبل اجرا می‌شود خاموش نشده و همان رله به کارش ادامه می‌دهد؛ حذفش نکنید. بعد از برگشتن Railway همین نصب را ادامه دهید. وضعیت: status.railway.com';
  if(/not authorized|unauthori[sz]ed|invalid token|forbidden|HTTP\s*(?:401|403)/i.test(s))return 'توکن Railway پذیرفته نشد یا دسترسی‌اش لغو شده؛ توکن حساب را دوباره بسازید و همان مقدار را وارد کنید.';
  if(/project token not found/i.test(s))return 'این توکن مخصوص یک پروژهٔ حذف‌شده است؛ توکن حساب (Account Token) بگذارید.';
  if(/rate limit|too many requests|HTTP\s*429/i.test(s))return 'Railway فعلاً درخواست‌های این حساب را محدود کرده؛ چند دقیقه بعد دوباره تلاش کنید.';
  if(/custom domains per service|limit for custom domains/i.test(s))return 'ظرفیت دامنهٔ اختصاصی این سرویس Railway پر است؛ سرویس دیگری را انتخاب کنید یا دامنهٔ رایگان Railway را نگه دارید.';
  if(/quota|exceeded|billing|trial/i.test(s))return 'سهمیه یا اعتبار حساب Railway اجازهٔ ساخت نمی‌دهد؛ پلن و اعتبار حساب را بررسی کنید.';
  if(/timeout|timed out|abort/i.test(s))return 'پاسخ Railway در زمان مجاز نرسید؛ دوباره تلاش کنید.';
  return 'سرویس بالادست خطا داد؛ متن اصلی در «جزئیات فنی» آمده است.';
}
