async function omniAoNativePrepare(env,row,selection){
 const p=selection.nativeEgress;if(p?.mode!=='r\u0061ilway-direct-nl-v1')return {pending:false};
 const vars={projectId:selection.projectId,environmentId:selection.environmentId,serviceId:selection.serviceId},token=row.railway_token;
 const cur=(await railwayGqlReq(token,'query($projectId:String!,$environmentId:String!,$serviceId:String!){variables(projectId:$projectId,environmentId:$environmentId,serviceId:$serviceId)}',vars)).variables||{};
 if(cur.TARGET_HOST!==row.worker_host||cur.TUNNEL_PATH!==row.tunnel_path)throw Error('\u0645\u0628\u062f\u0623 \u0627\u06cc\u0646 \u0633\u0631\u0648\u06cc\u0633 \u0645\u062a\u0639\u0644\u0642 \u0628\u0647 \u0647\u0645\u06cc\u0646 \u067e\u0646\u0644 \u0646\u06cc\u0633\u062a\u061b \u062a\u063a\u06cc\u06cc\u0631 \u0646\u06a9\u0631\u062f.');
 if(cur.OMNI_EGRESS_DOMAIN&&cur.OMNI_EGRESS_DOMAIN!==row.domain||cur.OMNI_EGRESS_KEY&&cur.OMNI_EGRESS_KEY!==p.authSecret)throw Error('\u062e\u0631\u0648\u062c\u06cc \u0627\u06cc\u0646 \u0633\u0631\u0648\u06cc\u0633 \u0628\u0631\u0627\u06cc \u0627\u062a\u0635\u0627\u0644 \u062f\u06cc\u06af\u0631\u06cc \u062b\u0628\u062a \u0634\u062f\u0647\u061b \u0628\u0627\u0632\u0646\u0648\u06cc\u0633\u06cc \u0646\u0634\u062f.');
 if(cur.NODE_OPTIONS&&![omniAoNativeNodeOptions,omniAoLegacyNativeNodeOptions,omniAoLegacyNativeNodeOptions2,omniAoHttpNodeOptions,"--import=data:text/javascript;base64,aW1wb3J0e2Jyb3RsaURlY29tcHJlc3NTeW5jIGFzIGR9ZnJvbSdub2RlOnpsaWInO2ltcG9ydCgnZGF0YTp0ZXh0L2phdmFzY3JpcHQ7YmFzZTY0LCcrZChCdWZmZXIuZnJvbShwcm9jZXNzLmVudi5PTU5JX1JULCdiYXNlNjQnKSkudG9TdHJpbmcoJ2Jhc2U2NCcpKTs="].includes(cur.NODE_OPTIONS))throw Error('\u06af\u0632\u06cc\u0646\u0647\u0654 Node \u0633\u0641\u0627\u0631\u0634\u06cc \u0627\u06cc\u0646 \u0633\u0631\u0648\u06cc\u0633 \u062d\u0641\u0638 \u0634\u062f\u061b \u0627\u062f\u063a\u0627\u0645 \u062f\u0633\u062a\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.');
 if(cur.OMNI_EGRESS_MODE!==p.mode||cur.NODE_OPTIONS!==omniAoNativeNodeOptions){
  const regions=(await railwayGqlReq(token,'query($p:String!){regions(projectId:$p){id name country}}',{p:selection.projectId})).regions||[],nl=regions.find(x=>x.country==='Netherlands'&&x.id==='ams')||regions.find(x=>x.country==='Netherlands');if(!nl)throw Error('\u0647\u0644\u0646\u062f \u062f\u0631 \u0647\u0645\u06cc\u0646 \u067e\u0631\u0648\u0698\u0647 \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a\u061b \u0622\u0645\u0631\u06cc\u06a9\u0627 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0646\u0634\u062f.');
  await railwayGqlReq(token,'mutation($s:String!,$e:String!,$i:ServiceInstanceUpdateInput!){serviceInstanceUpdate(serviceId:$s,environmentId:$e,input:$i)}',{s:selection.serviceId,e:selection.environmentId,i:{region:nl.name,multiRegionConfig:{[nl.id]:{numReplicas:1}}}});
  await railwayGqlReq(token,'mutation($i:VariableCollectionUpsertInput!){variableCollectionUpsert(input:$i)}',{i:{...vars,skipDeploys:true,variables:{NODE_OPTIONS:omniAoNativeNodeOptions,OMNI_EGRESS_MODE:p.mode,OMNI_EGRESS_KEY:p.authSecret,OMNI_EGRESS_DOMAIN:row.domain,OMNI_RT:omniAoNativeRuntime}}});
  await railwayGqlReq(token,'mutation($s:String!,$e:String!){serviceInstanceDeploy(serviceId:$s,environmentId:$e)}',{s:selection.serviceId,e:selection.environmentId});return {pending:true};
 }
 const d=(await railwayGqlReq(token,'query($projectId:String!,$environmentId:String!,$serviceId:String!){domains(projectId:$projectId,environmentId:$environmentId,serviceId:$serviceId){serviceDomains{domain}}}',vars)).domains?.serviceDomains?.find(x=>/^[-a-z0-9]+\.up\.r\u0061ilway\.app$/.test(x.domain));if(!d)throw Error('\u0646\u0634\u0627\u0646\u06cc \u0639\u0645\u0648\u0645\u06cc \u0647\u0645\u0627\u0646 \u0633\u0631\u0648\u06cc\u0633 \u067e\u06cc\u062f\u0627 \u0646\u0634\u062f.');
 const r=await fetch('https://'+d.domain+'/_omni/nl-egress-check',{headers:{authorization:'Bearer '+p.authSecret},redirect:'manual',signal:AbortSignal.timeout(12000)});if(r.status>=300&&r.status<400){await r.body?.cancel();throw Error('Unexpected redirect from selected R\u0061ilway service; credentials were not forwarded.');}if(r.status===404||r.status>=500)return {pending:true};const geo=await r.json();if(!r.ok||geo.countryCode!=='NL')throw Error('\u062e\u0631\u0648\u062c\u06cc \u0648\u0627\u0642\u0639\u06cc \u0647\u0644\u0646\u062f \u062a\u0623\u06cc\u06cc\u062f \u0646\u0634\u062f\u061b \u067e\u0631\u0686\u0645 \u0647\u0644\u0646\u062f \u0627\u0639\u0645\u0627\u0644 \u0646\u0634\u062f.');
 if(!p.verifiedAt){const addresses=await omniAoDirectAddresses(row);p.countryCode='NL';p.exitIP=geo.ip;p.verifiedAt=new Date().toISOString();p.catalogOnlyArvan=true;p.verifiedProfiles=addresses.flatMap(address=>omniAoDirectTlsPorts.flatMap(port=>['w\u0073','x\u0068ttp'].map(transport=>({address,port,transport,verified:false}))));p.verificationScope='Netherlands server egress verified; each new domain/carrier route is an explicitly unverified candidate';await env.DB.prepare('UPDATE arvan_owned_jobs SET fork_selection=? WHERE id=?').bind(JSON.stringify(selection),row.id).run();}
 const settings=await settingsCached(env);if(!settings.arvan_primary_job||settings.arvan_primary_job===row.id)await env.DB.prepare("INSERT INTO settings(key,value)VALUES('arvan_primary_job',?) ON CONFLICT(key)DO UPDATE SET value=excluded.value").bind(row.id).run();return {pending:false};
}



