 const cur=(await railwayGqlReq(token,'query($projectId:String!,$environmentId:String!,$serviceId:String!){variables(projectId:$projectId,environmentId:$environmentId,serviceId:$serviceId)}',vars)).variables||{};
 if(cur.TARGET_HOST!==row.worker_host||cur.TUNNEL_PATH!==row.tunnel_path)throw Error('\u0645\u0628\u062f\u0623 \u0627\u06cc\u0646 \u0633\u0631\u0648\u06cc\u0633 \u0645\u062a\u0639\u0644\u0642 \u0628\u0647 \u0647\u0645\u06cc\u0646 \u067e\u0646\u0644 \u0646\u06cc\u0633\u062a\u061b \u062a\u063a\u06cc\u06cc\u0631 \u0646\u06a9\u0631\u062f.');
