 if(arvanReady.length){
  for(const r of arvanReady){
   const mci=typeof omniAoMciNativeProfiles==='f\u0075nction'?omniAoMciNativeProfiles(r,user):[];
   if(mci?.length)result.push(...mci.map(x=>x.uri));
   const native=mci?.length?null:(typeof omniAoNativeProfiles==='f\u0075nction'?omniAoNativeProfiles(r,user):null);
   if(native?.length)result.push(...native.map(x=>x.uri));
   else if(!mci?.length&&r.domain)result.push(omniAoDirectUri(r,user,r.domain));
  }
 }
