 for(const r of saved){const list=JSON.parse(r.uris);if(Array.isArray(list))result.push(...list);}
 for(const r of groups){if(arvanReady.length&&String(r.source||'').startsWith('a\u0072van:'))continue;const a=JSON.parse(r.uris);if(Array.isArray(a))result.push(...a);}
