 const bridges=await omniCreatedRows(env,"SELECT platform,domain,tunnel_path FROM bot_bridges WHERE status='ready' AND platform IN ('d\u0065no','r\u0065nder','f\u0061lix','r\u0061ilway','railway_arvan')");
