async function omniBillingConfig(request, env2, url, settings) {
  const reply = (d, s = 200) => Response.json(d, { status: s, headers: { "cache-control": "no-store" } });
  if (request.method !== "POST") return reply({ ok: false, error: "روش نامعتبر است." }, 405);
  const b = await request.json().catch(() => ({}));
  const patch = {};
  const hostRe = /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9-]{2,}(?::\d{1,5})?$/;
  if (typeof b.arvan_manager_url === "string") {
    const v = b.arvan_manager_url.trim().replace(/\/+$/, "");
    if (v && !/^https:\/\/[a-z0-9.-]+$/i.test(v)) return reply({ ok: false, error: "آدرس مدیر آروان باید با https:// شروع شود." }, 400);
    patch.arvan_manager_url = v;
  }
  if (typeof b.mesh_peer_host === "string") {
    const v = b.mesh_peer_host.trim().toLowerCase().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
    if (v && !hostRe.test(v)) return reply({ ok: false, error: "هاست پیر معتبر نیست." }, 400);
    patch.mesh_peer_host = v;
  }
  if (typeof b.public_host === "string" && b.public_host.trim()) {
    const v = b.public_host.trim().toLowerCase().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
    if (!hostRe.test(v)) return reply({ ok: false, error: "دامنهٔ پنل معتبر نیست." }, 400);
    patch.public_host = v;
  }
  for (const [k, v] of Object.entries(patch)) await putSetting(env2, k, String(v));
  return reply({ ok: true, saved: patch });
}
