 if(!env.DB)throw Error('\u0642\u0641\u0644 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u0645\u0648\u062c\u0648\u062f \u0646\u06cc\u0633\u062a\u061b \u0647\u06cc\u0686 \u0686\u06cc\u0632\u06cc \u062d\u0630\u0641 \u0646\u0634\u062f.');
