 const now=Date.now(),r=await env.DB.prepare("INSERT INTO bot_doctor_recreate_lock(scope,at,phase)VALUES(?,?,'preparing') ON CONFLICT(scope)DO UPDATE SET at=excluded.at,phase='preparing',resume_count=0 WHERE bot_doctor_recreate_lock.at<? OR (bot_doctor_recreate_lock.phase='preparing' AND bot_doctor_recreate_lock.at<?)").bind(omniDoctorKey(panel,'lock'),now,now-21600000,now-300000).run();return Number(r.m\u0065ta?.changes||0)===1;
