 const box=await omniDoctorRead(env,panel,state.backupKey);if(!box)throw Error('\u0628\u06a9\u0627\u067e \u0645\u0631\u062d\u0644\u0647\u0654 \u0646\u06cc\u0645\u0647\u200c\u062a\u0645\u0627\u0645 \u0645\u0648\u062c\u0648\u062f \u0646\u06cc\u0633\u062a\u061b \u062f\u06cc\u062a\u0627\u0628\u06cc\u0633 \u062f\u0633\u062a\u200c\u0646\u062e\u0648\u0631\u062f\u0647 \u0627\u0633\u062a.');const backup=await omniDoctorDecrypt(env,box);if(backup.accountId!==panel.account_id||backup.workerName!==panel.worker_name||backup.databaseId!==panel.database_id)throw Error('\u0628\u06a9\u0627\u067e \u0628\u0647 \u0627\u06cc\u0646 \u067e\u0646\u0644 \u062a\u0639\u0644\u0642 \u0646\u062f\u0627\u0631\u062f.');
 await omniDoctorStillOwned(env,panel);
 if(!await omniDoctorClaimResume(env,panel))return omniDoctorResult(panel,health,{pending:true,message:'\u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u062f\u0631 \u062c\u0631\u06cc\u0627\u0646 \u0627\u0633\u062a \u06cc\u0627 \u0633\u0642\u0641 \u062a\u0644\u0627\u0634 \u0622\u0646 \u0641\u0639\u0627\u0644 \u0627\u0633\u062a\u061b \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0647\u0645\u0632\u0645\u0627\u0646 \u0627\u062c\u0631\u0627 \u0646\u0634\u062f.'});
 const form=new FormData();form.append('metadata',new Blob([JSON.stringify(backup.metadata)],{type:'application/json'}),'metadata.json');form.append('worker.js',new Blob([backup.source],{type:'application/javascript+module'}),'worker.js');await omniDoctorWrite(env,panel,'state',{...state,resumeAttempts:(state.resumeAttempts||0)+1});const put=await fetch('https://api.cloudflare.com/client/v4'+base,{method:'PUT',headers:{authorization:'Bearer '+token},body:form,signal:AbortSignal.timeout(12000)});const j=await put.json();if(!put.ok||!j.success)throw Error('\u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0632\u0633\u0627\u0632\u06cc \u06a9\u0627\u0645\u0644 \u0646\u0634\u062f\u061b \u0628\u06a9\u0627\u067e \u0648 \u062f\u06cc\u062a\u0627\u0628\u06cc\u0633 \u0645\u062d\u0641\u0648\u0638\u200c\u0627\u0646\u062f.');
