async function omniDoctorRememberToken(env,panel,token){const policy=await omniDoctorRead(env,panel,'policy');if(!omniDoctorPolicyMatches(policy,panel)||!token||!env.BOT_TOKEN)return;const old=await omniDoctorRead(env,panel,'credential');if(old){try{const saved=await omniDoctorDecrypt(env,old);if(saved.token===token&&saved.accountId===panel.account_id&&saved.databaseId===panel.database_id)return;}catch{}}await omniDoctorWrite(env,panel,'credential',await omniDoctorEncrypt(env,{token,accountId:panel.account_id,databaseId:panel.database_id,workerName:panel.worker_name,ownerChatId:String(panel.owner_chat_id),at:Date.now()}));}
async function omniDoctorRepairToken(env,panel){const cached=await getCachedToken(env,panel.owner_chat_id).catch(()=>'');if(cached)return cached;const policy=await omniDoctorRead(env,panel,'policy');if(!omniDoctorPolicyMatches(policy,panel))return '';const box=await omniDoctorRead(env,panel,'credential');if(!box)return '';try{const saved=await omniDoctorDecrypt(env,box);return saved.accountId===panel.account_id&&saved.databaseId===panel.database_id&&saved.workerName===panel.worker_name&&saved.ownerChatId===String(panel.owner_chat_id)?saved.token:'';}catch{return '';}}

async function omniDoctorStillOwned(env,panel){const live=await env.DB.prepare('SELECT deleted_at,account_id,database_id,owner_chat_id FROM bot_panels WHERE id=?').bind(Number(panel.id)).first();if(!live||live.deleted_at||live.account_id!==panel.account_id||live.database_id!==panel.database_id||String(live.owner_chat_id)!==String(panel.owner_chat_id))throw Error('\u0645\u0627\u0644\u06a9 \u067e\u0646\u0644 \u06cc\u0627 \u062f\u06cc\u062a\u0627\u0628\u06cc\u0633 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u062f\u0627\u062f\u0647 \u06cc\u0627 \u062d\u0630\u0641 \u06a9\u0631\u062f\u0647 \u0627\u0633\u062a\u061b \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u0644\u063a\u0648 \u0634\u062f.');}

async function omniDoctorClaimResume(env,panel){const now=Date.now(),r=await env.DB.prepare("UPDATE bot_doctor_recreate_lock SET phase='resuming',at=?,resume_count=resume_count+1 WHERE scope=? AND resume_count<2 AND (phase='recreating' OR (phase='resuming' AND at<?))").bind(now,omniDoctorKey(panel,'lock'),now-180000).run();return Number(r.m\u0065ta?.changes||0)===1;}

