  // /projects is optional: many existing keys only grant deployments:read.
  // When projects:read is present, merge project names so empty/offline projects
  // are still visible instead of silently appearing as “0 found”.
  let projectRows = [];
  try {
    const projectListing = await ovBothFetch(key, "/projects", 8000);
    projectRows = Array.isArray(projectListing.projects) ? projectListing.projects : Array.isArray(projectListing.data && projectListing.data.projects) ? projectListing.data.projects : [];
  } catch (_) {}
  const projectById = new Map();
  for (const project of projectRows) {
    const id = String(project && project.id || "").trim();
    if (/^[A-Za-z0-9_-]{1,128}$/.test(id)) projectById.set(id, project);
  }
  const byId = new Map();
  for (const item of all) {
    const id = String(typeof item === "string" ? item : item && item.id || "").trim();
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(id)) continue;
    byId.set(id, { ...(typeof item === "object" && item ? item : {}), id });
  }
  for (const project of projectRows) {
    const id = String(project && project.id || "").trim();
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(id)) continue;
    const old = byId.get(id) || {};
    byId.set(id, { ...project, ...old, id, _project_only: !Object.keys(old).some((k) => k !== "id") });
  }
  const allCandidates = [...byId.values()];
  if (selectedId && !byId.has(selectedId)) ovFail("این پروژه در حساب Bot-Hosting مربوط به همین کلید پیدا نشد.", 400);
  const limit = selectedId ? 1 : 40;
  const candidates = selectedId ? [byId.get(selectedId)] : allCandidates.slice(0, limit);
  const liveStates = new Set(["running", "active", "ready", "online"]);
  const results = [];
  for (const item of candidates) {
    const id = String(item && item.id || "").trim();
    if (!id) continue;
    let deployment = { ...item };
    const hasDetails = Boolean(deployment.state || deployment.domains || deployment.entryFile || deployment.runtime);
    if (!hasDetails || deployment._project_only) {
      try {
        const detail = await ovBothFetch(key, "/deployments/" + encodeURIComponent(id), 10000);
        const record = detail.deployment || detail;
        deployment = { ...deployment, ...record, id };
      } catch (_) {}
    }
    let entryFile = String(deployment.entryFile || deployment.startup && deployment.startup.entryFile || "");
    if (!entryFile) {
      try {
        const startupResult = await ovBothFetch(key, "/deployments/" + encodeURIComponent(id) + "/startup", 7000);
        const startup = startupResult.startup || startupResult;
        deployment = { ...deployment, startup };
        entryFile = String(startup.entryFile || startup.entry_file || "");
      } catch (_) {}
    }
    const state = String(deployment.state || deployment.runtimeState || "unknown").trim().toLowerCase();
    const host = ovAppsHost(deployment);
    let path = ovPathFromDeployment(deployment);
    if (!path) {
      const cached = await env.DB.prepare("SELECT ws_path FROM managed_bothost_jobs WHERE deployment_id=? AND status='ready'").bind(id).first().catch(() => null);
      const cachedPath = String(cached && cached.ws_path || "");
      if (/^\/[A-Za-z0-9_/-]{1,99}$/.test(cachedPath) && !cachedPath.includes("//") && !cachedPath.includes("..")) path = cachedPath;
    }
    if (!path) path = await ovReadRelayPath(key, { ...deployment, id, entryFile });
    const canRelay = liveStates.has(state) && Boolean(host) && Boolean(path);
    const reason = !host ? "no_public_apps_host" : !liveStates.has(state) ? "deployment_not_running" : !path ? "private_ws_path_not_found" : "";
    const project = projectById.get(String(deployment.projectId || deployment.project_id || id));
    results.push({
      id, name: String(deployment.name || project && project.name || id).slice(0, 100), state,
      owned: deployment.owned !== false, apps_host: host, path,
      runtime: String(deployment.runtime || deployment.startup && deployment.startup.runtime || ""),
      entry_file: entryFile,
      project_id: String(deployment.projectId || deployment.project_id || project && project.id || ""),
      can_relay: canRelay, reason
    });
  }
  if (selectedId) {
    const selected = results.find((item) => item.id === selectedId);
    if (!selected) ovFail("پروژه پیدا شدنی نبود؛ فهرست را تازه کن و دوباره انتخاب کن.", 400);
    if (!selected.can_relay) {
      const label = selected.name || selected.id;
      if (selected.reason === "deployment_not_running")
        ovFail("پروژهٔ «" + label + "» پیدا شد، اما وضعیت Bot-Hosting آن «" + selected.state + "» است؛ تا وقتی برنامه در حالت running نباشد، رلهٔ Vercel کار نمی‌کند.", 400);
      if (selected.reason === "private_ws_path_not_found")
        ovFail("پروژهٔ «" + label + "» پیدا شد، اما مسیر خصوصی WebSocket در اطلاعات یا فایل شروع" + (selected.entry_file ? " «" + selected.entry_file + "»" : "") + " پیدا نشد؛ کانفیگ قابل‌اتکا ساخته نمی‌شود.", 400);
      ovFail("پروژهٔ «" + label + "» پیدا شد، اما هاست عمومی apps.bot-hosting.cloud ندارد.", 400);
    }
  }
